        var targetYaw = expected.AngularVelocity + yawDelta;
        var targetBeta = expected.SlideRadians + .3 * BikeAngles.Wrap(target.Beta - expected.SlideRadians) * ramp;
        double targetSpeed = expected.Speed + speedDelta;

